/** Method of interpolation between this key and the next. */
UENUM(BlueprintType)
enum ERichCurveInterpMode : int
{
	/** Use linear interpolation between values. */
	RCIM_Linear UMETA(DisplayName = "Linear"),
	/** Use a constant value. Represents stepped values. */
	RCIM_Constant UMETA(DisplayName = "Constant"),
	/** Cubic interpolation. See TangentMode for different cubic interpolation options. */
	RCIM_Cubic UMETA(DisplayName = "Cubic"),
	/** No interpolation. */
	RCIM_None UMETA(Hidden)
};

/** Enumerates extrapolation options. */
UENUM(BlueprintType)
enum ERichCurveExtrapolation : int
{
	/** Repeat the curve without an offset. */
	RCCE_Cycle UMETA(DisplayName = "Cycle"),
	/** Repeat the curve with an offset relative to the first or last key's value. */
	RCCE_CycleWithOffset UMETA(DisplayName = "CycleWithOffset"),
	/** Sinusoidally extrapolate. */
	RCCE_Oscillate UMETA(DisplayName = "Oscillate"),
	/** Use a linearly increasing value for extrapolation.*/
	RCCE_Linear UMETA(DisplayName = "Linear"),
	/** Use a constant value for extrapolation */
	RCCE_Constant UMETA(DisplayName = "Constant"),
	/** No Extrapolation */
	RCCE_None UMETA(DisplayName = "None")

float EvalForTwoKeys(const FRichCurveKey& Key1, const FRichCurveKey& Key2, const float InTime)
{
	const float Diff = Key2.Time - Key1.Time;

	if (Diff > 0.f)
	{
		if (Key1.InterpMode != RCIM_Constant)
		{
			const float Alpha = (InTime - Key1.Time) / Diff;
			const float P0 = Key1.Value;
			const float P3 = Key2.Value;

			if (Key1.InterpMode == RCIM_Linear)
			{
				return FMath::Lerp(P0, P3, Alpha);
			}
			else 
			{					
				if (IsItNotWeighted(Key1,Key2))
				{
					const float OneThird = 1.0f / 3.0f;
					const float P1 = P0 + (Key1.LeaveTangent * Diff * OneThird);
					const float P2 = P3 - (Key2.ArriveTangent * Diff * OneThird);

					return BezierInterp(P0, P1, P2, P3, Alpha);
				}
				//if (IsWeighted(Key1, Key2))//it's weighted
				else	
				{
				return WeightedEvalForTwoKeys(
					Key1.Value, Key1.Time, Key1.LeaveTangent, Key1.LeaveTangentWeight, Key1.TangentWeightMode,
					Key2.Value, Key2.Time, Key2.ArriveTangent, Key2.ArriveTangentWeight, Key2.TangentWeightMode,
					InTime);
				}
			}
		}

	// Get acceleration, deceleration and ground friction using a curve. This
	// allows us to precisely control the movement behavior at each speed.

	if (ALS_ENSURE(IsValid(GaitSettings.AccelerationAndDecelerationAndGroundFrictionCurve)))
	{
		const auto& AccelerationAndDecelerationAndGroundFrictionCurves{
			GaitSettings.AccelerationAndDecelerationAndGroundFrictionCurve->FloatCurves
		};

		MaxAccelerationWalking = AccelerationAndDecelerationAndGroundFrictionCurves[0].Eval(GaitAmount);
		BrakingDecelerationWalking = AccelerationAndDecelerationAndGroundFrictionCurves[1].Eval(GaitAmount);
		GroundFriction = AccelerationAndDecelerationAndGroundFrictionCurves[2].Eval(GaitAmount);
	}
}

